import {
  ACHIEVEMENTS,
  ASCENSION_TIERS,
  DEEP_SPACE_DISCOVERIES,
  ENDGAME_RELICS,
  PRESTIGE_DATA,
  SOUNDSCAPES,
  SOURCE_DATA,
  STORY_BEATS,
  STORY_CHAPTERS,
  UPGRADE_DATA
} from './data.js';
import { createInitialState, createSources } from './state.js';

const MIN_CHAIN_REWARD_RATIO = 0.4;
const SOFT_CAP_RAW_LIMIT = 256;
const MIN_WAVE_VALUE = 0.015;
const MAX_DELTA = 0.1;

export function getFrequencyRelation(first, second, interferenceBoost = false) {
  const distance = Math.abs(first - second);
  if (distance < 5) return { type: 'interference', multiplier: interferenceBoost ? 0.7 : 0.5 };
  if (distance >= 47 && distance <= 53) return { type: 'octave', multiplier: 2 };
  if (distance >= 32 && distance <= 42) return { type: 'fifth', multiplier: 1.5 };
  if (distance >= 15 && distance <= 25) return { type: 'third', multiplier: 1.25 };
  return { type: 'neutral', multiplier: 1 };
}

export function getSoftCappedEcho(value, base) {
  let softened = Math.min(value, base);
  let threshold = base;
  for (let stage = 0; stage < 8; stage++) {
    const width = base * 2 ** stage;
    const portion = Math.min(width, Math.max(0, value - threshold));
    softened += width * (Math.sqrt(1 + portion / width) - 1);
    threshold += width;
  }
  return softened;
}

export function loadLegacyState(saved, sourceData = SOURCE_DATA) {
  const state = createInitialState();
  const d = saved && typeof saved === 'object' ? saved : {};
  const legacyEndgame = d.endgame && typeof d.endgame === 'object' ? d.endgame : {};
  state.sources = createSources(sourceData);
  state.breath = finiteNonNegative(d.breath, state.breath);
  state.echo = finiteNonNegative(d.echo);
  state.silence = finiteNonNegative(d.silence);
  state.lifetimeEcho = finiteNonNegative(d.lifetimeEcho);
  state.lifetimeSilence = finiteNonNegative(d.lifetimeSilence);
  state.totalSilenceSpent = finiteNonNegative(d.totalSilenceSpent);
  state.frequency = clampInteger(d.freq, 0, 100, 50);
  state.echoPoints = finiteNonNegative(d.echoPoints);
  state.eternalLevel = Math.floor(finiteNonNegative(d.permLevel));
  state.cosmicTier = clampInteger(d.endgame?.cosmicTier, 0, ASCENSION_TIERS.length, 0);
  state.globalBonus = finiteNonNegative(d.globalMult, 1) || 1;
  state.resonance = finiteNonNegative(d.resonance);
  const legacySilenceProgress = state.eternalLevel === 0
    ? state.lifetimeSilence
    : state.silence;
  state.silenceThisCycle = finiteNonNegative(d.silenceThisCycle, legacySilenceProgress);
  state.soundEnabled = d.soundOn !== false;
  state.language = d.language === 'en-US' ? 'en-US' : 'zh-CN';
  state.theme = ['dark', 'light', 'cyber'].includes(d.theme) ? d.theme : 'dark';
  state.levels = { ...state.levels, ...safeNumericRecord(d.lv, Object.keys(state.levels)) };
  state.permanent = { ...state.permanent, ...safeNumericRecord(d.prestigeLv, Object.keys(state.permanent)) };
  state.soundscapes = state.soundscapes.map((_, index) => Boolean(d.ambience?.[index]));
  state.achievements = safeBooleanRecord(d.achievements);
  state.discoveries = Object.fromEntries(DEEP_SPACE_DISCOVERIES.map(discovery => [
    discovery.id,
    Boolean(legacyEndgame.discoveries?.[discovery.id])
  ]));
  state.storyBeats = Object.fromEntries(STORY_BEATS.map(beat => [
    beat.id,
    Boolean(legacyEndgame.storyBeats?.[beat.id])
  ]));
  state.interferenceBoost = Boolean(d.interfereBuff);
  state.silenceBoost = Boolean(d.silenceBoost);
  state.freeDecayChains = Math.floor(finiteNonNegative(d.pendingSilenceCount));
  state.lastChain = normalizeLastChain(d.lastChainInfo);
  const savedStats = safeNumericRecord(d.stats, Object.keys(state.stats));
  savedStats.maxChainGenerations = Math.max(
    savedStats.maxChainGenerations || 0,
    finiteNonNegative(d.stats?.maxChainGen)
  );
  state.stats = { ...state.stats, ...savedStats };
  state.stardust = finiteNonNegative(legacyEndgame.stardust);
  state.relics = Object.fromEntries(ENDGAME_RELICS.map(relic => [
    relic.id,
    clampInteger(legacyEndgame.relics?.[relic.id], 0, relic.max, 0)
  ]));
  state.sources = state.sources.map((source, index) => {
    const previous = d.sources?.[index];
    return {
      ...source,
      unlocked: Boolean(previous?.unlocked),
      frequency: clampInteger(previous?.freq, 0, 100, source.frequency),
      timer: finiteNonNegative(previous?.timer) % source.interval
    };
  });
  delete state.levels.gen;
  return state;
}

function finiteNonNegative(value, fallback = 0) {
  const number = Number(value);
  return Number.isFinite(number) ? Math.max(0, number) : fallback;
}

function clampInteger(value, minimum, maximum, fallback) {
  const number = Number(value);
  if (!Number.isFinite(number)) return fallback;
  return Math.max(minimum, Math.min(maximum, Math.trunc(number)));
}

function safeNumericRecord(record, allowedKeys) {
  if (!record || typeof record !== 'object') return {};
  return Object.fromEntries(allowedKeys.flatMap(key => {
    const value = Number(record[key]);
    return Number.isFinite(value) && value >= 0 ? [[key, value]] : [];
  }));
}

function safeBooleanRecord(record) {
  if (!record || typeof record !== 'object') return {};
  return Object.fromEntries(Object.entries(record).map(([key, value]) => [key, Boolean(value)]));
}

function normalizeLastChain(value) {
  if (!value || typeof value !== 'object') return null;
  const V0 = Number(value.V0);
  const frequency = Number(value.freq);
  return Number.isFinite(V0) && V0 > 0 && Number.isFinite(frequency)
    ? { V0, frequency: Math.max(0, Math.min(100, Math.trunc(frequency))) }
    : null;
}

export class GameEngine {
  constructor(state = createInitialState()) {
    this.state = state;
    this.state.storyBeats = Object.fromEntries(STORY_BEATS.map(beat => [
      beat.id,
      Boolean(this.state.storyBeats?.[beat.id])
    ]));
    this.state.discoveries = Object.fromEntries(DEEP_SPACE_DISCOVERIES.map(discovery => [
      discovery.id,
      Boolean(this.state.discoveries?.[discovery.id])
    ]));
    if (!this.state.sources.length) this.state.sources = createSources(SOURCE_DATA);
    this.events = [];
    this.recompute();
    this.checkDiscoveries();
    this.checkStoryMilestones(false);
  }

  emitEvent(type, payload = {}) {
    this.events.push({ type, ...payload });
  }

  drainEvents() {
    return this.events.splice(0);
  }

  recompute() {
    const s = this.state;
    s.v0 = 10 + 8 * s.levels.vocal;
    s.polyphony = 1 + s.levels.poly + (s.soundscapes[2] ? 1 : 0);
    s.retention = Math.min(1.05, 0.8 + 0.025 * s.levels.reso);
    s.decay = Math.min(0.9, 0.5 + 0.01 * s.levels.decay);
    const layerBreathBonus = ASCENSION_TIERS.slice(0, s.cosmicTier)
      .reduce((bonus, tier) => bonus + (tier.breathBonus || 0), 0);
    s.breathRate = (0.5 + 0.1 * s.levels.breath) * (s.soundscapes[0] ? 1.3 : 1) * (1 + layerBreathBonus);
    s.maxBreath = 20 + 10 * s.levels.breath + s.permanent.initBreath * 10;
    s.tuned = s.levels.tune > 0;
    s.breath = Math.min(s.breath, s.maxBreath);
  }

  globalMultiplier() {
    const s = this.state;
    let multiplier = (1 + s.echoPoints * 0.1)
      * (1 + Math.floor(s.resonance / 100) * 0.1)
      * (1 + 0.08 * s.levels.eff)
      * (1 + 0.06 * s.levels.harmonics)
      * (s.globalBonus || 1);
    if (s.soundscapes[3]) multiplier *= 1.5;
    multiplier *= 1 + s.permanent.echoBoost * 0.2 + s.permanent.deepMemory * 0.05;
    multiplier *= 1 + s.relics.prism * 0.05;
    for (const tier of ASCENSION_TIERS.slice(0, s.cosmicTier)) multiplier *= tier.bonus;
    const discoveryBonus = DEEP_SPACE_DISCOVERIES.reduce(
      (total, discovery) => total + (s.discoveries[discovery.id] ? discovery.bonus : 0),
      0
    );
    multiplier *= 1 + discoveryBonus;
    return multiplier;
  }

  checkDiscoveries() {
    const s = this.state;
    for (const discovery of DEEP_SPACE_DISCOVERIES) {
      if (s.discoveries[discovery.id]) continue;
      const unlocked = s.cosmicTier >= discovery.tier
        && s.lifetimeEcho >= discovery.lifetimeEcho
        && s.stats.resonated >= discovery.resonances
        && s.stats.maxChainGenerations >= discovery.generations
        && s.lifetimeSilence >= (discovery.lifetimeSilence || 0);
      if (!unlocked) continue;
      s.discoveries[discovery.id] = true;
      this.emitEvent('discovery', { id: discovery.id, name: discovery.name });
      this.recordStoryBeat(`discovery_${discovery.id}`);
    }
  }

  recordStoryBeat(id, announce = true) {
    const beat = STORY_BEATS.find(item => item.id === id);
    if (!beat || this.state.storyBeats[beat.id]) return false;
    this.state.storyBeats[beat.id] = true;
    if (announce) this.emitEvent('story', { id: beat.id, title: beat.title, text: beat.text });
    return true;
  }

  checkStoryMilestones(announce = true) {
    const s = this.state;
    const record = id => this.recordStoryBeat(id, announce);
    if (s.stats.emitted > 0) record('first_emit');
    if (Object.values(s.levels).some(level => level > 0)) record('first_upgrade');
    if (s.lifetimeEcho >= 1000) record('first_echoes');
    if (s.stats.interfered > 0) record('first_interference');
    if (s.stats.resonated > 0) record('first_resonance');
    if (s.stats.maxChainGenerations >= 50) record('long_chain');
    if (s.sources.some(source => source.unlocked)) record('first_source');
    if (s.sources.length > 0 && s.sources.every(source => source.unlocked)) record('all_sources');
    if (s.soundscapes.some(Boolean)) record('first_soundscape');
    if (s.lifetimeSilence > 0) record('first_silence');
    if (s.eternalLevel >= 1) record('first_prestige');
    if (s.eternalLevel >= 2) record('eternal_two');
    if (Object.values(s.relics).some(level => level > 0)) record('relic_first');
  }

  speedMultiplier() {
    const s = this.state;
    const layerBonus = ASCENSION_TIERS.slice(0, s.cosmicTier)
      .reduce((bonus, tier) => bonus + (tier.speedBonus || 0), 0);
    return (s.soundscapes[4] ? 1.3 : 1) * (1 + s.relics.engine * 0.02 + layerBonus);
  }

  comboMultiplier() {
    return 1 + Math.min(this.state.combo, 10) * 0.1;
  }

  getUpgradeCost(upgrade) {
    return upgrade.base * upgrade.growth ** this.state.levels[upgrade.id];
  }

  getPrestigeCost(upgrade) {
    return upgrade.base * upgrade.growth ** this.state.permanent[upgrade.id];
  }

  getFinalCost() {
    return Math.floor(1000 * 3 ** this.state.eternalLevel);
  }

  getPrestigeGain() {
    const s = this.state;
    const baseGain = Math.floor(Math.sqrt(s.silenceThisCycle / 50)) + s.eternalLevel * 2;
    return Math.floor(baseGain * (1 + s.relics.archive * 0.05));
  }

  silenceReward(generations) {
    const s = this.state;
    let bonus = s.levels.seren + s.levels.aftertone * 0.5 + (s.soundscapes[1] ? 1 : 0) + (s.silenceBoost ? 1 : 0);
    let base = 0;
    if (generations >= 75) base = 12;
    else if (generations >= 50) base = 7;
    else if (generations >= 35) base = 4;
    else if (generations >= 25) base = 2;
    else if (generations >= 12) base = 1;
    const layerBonus = ASCENSION_TIERS.slice(0, s.cosmicTier)
      .reduce((sum, tier) => sum + (tier.silenceBonus || 0), 0);
    return base > 0
      ? (base + bonus) * (s.permanent.serenBoost > 0 ? 1.5 : 1) * (1 + s.relics.ember * 0.1) * (1 + layerBonus)
      : 0;
  }

  planChain(start, ignoresDecay = false, collect = true) {
    const s = this.state;
    const generations = [];
    let vibration = start;
    let count = 0;
    let total = 0;
    const decayRatio = ignoresDecay ? 1 : s.decay * s.retention;
    const decays = !ignoresDecay && decayRatio < 1;
    const softCapped = !decays;
    const cap = decays ? Infinity : Math.ceil(256 / (s.decay * MIN_CHAIN_REWARD_RATIO));

    while (count < cap) {
      if (vibration <= MIN_WAVE_VALUE) break;
      const gain = vibration * s.decay;
      let next = ignoresDecay ? vibration : gain * s.retention;
      if (decays && (next >= vibration || next <= MIN_WAVE_VALUE)) next = 0;
      if (collect) generations.push({ vibration, gain, nextVibration: next });
      total += gain;
      count++;
      vibration = next;
    }

    return { generations, count, total, softCapped };
  }

  createChain(start, frequency, ignoresDecay = false, chorus = false) {
    const plan = this.planChain(start, ignoresDecay);
    const capBase = Math.max(1, Math.min(Number.MAX_VALUE / 512, start * this.globalMultiplier()));
    const interval = 0.4 / this.speedMultiplier();
    return {
      start,
      frequency,
      ignoresDecay,
      chorus,
      softCapped: plan.softCapped,
      capBase,
      alive: true,
      generations: plan.generations,
      generationIndex: 0,
      elapsed: 0,
      interval,
      nextAt: interval,
      earned: 0,
      rawEarned: 0,
      softenedEarned: 0
    };
  }

  activeChains(ordinaryOnly = false) {
    return this.state.chains.filter(chain => chain.alive && (!ordinaryOnly || !chain.chorus));
  }

  chainMultiplier(chain) {
    if (chain.chorus) return this.globalMultiplier() * 1.5;
    let interference = false;
    let best = 1;
    for (const other of this.activeChains(true)) {
      if (other === chain) continue;
      const relation = getFrequencyRelation(chain.frequency, other.frequency, this.state.interferenceBoost);
      if (relation.type === 'interference') interference = true;
      else best = Math.max(best, relation.multiplier);
    }
    const multiplier = interference ? (this.state.interferenceBoost ? 0.7 : 0.5) : best;
    const crowdPenalty = !this.state.tuned && this.activeChains(true).length > 5 ? 0.8 : 1;
    return multiplier * crowdPenalty * this.globalMultiplier();
  }

  checkAchievement(id) {
    const s = this.state;
    if (s.achievements[id]) return;
    const achievement = ACHIEVEMENTS.find(item => item.id === id);
    if (!achievement) return;
    s.achievements[id] = true;
    switch (achievement.reward) {
      case 'firstEmit': s.globalBonus = (s.globalBonus || 1) * 1.05; break;
      case 'interference': s.interferenceBoost = true; break;
      case 'resonance': s.globalBonus = (s.globalBonus || 1) * 1.1; break;
      case 'silence': s.silenceBoost = true; break;
      case 'million': s.globalBonus = (s.globalBonus || 1) * 1.1; break;
      case 'prestige': s.globalBonus = (s.globalBonus || 1) * 1.2; break;
      case 'longChain': s.globalBonus = (s.globalBonus || 1) * 1.1; break;
      case 'sources': s.globalBonus = (s.globalBonus || 1) * 1.15; break;
    }
    this.emitEvent('achievement', { id, name: achievement.name });
  }

  settle(chain) {
    if (chain.generationIndex >= chain.generations.length) {
      this.endChain(chain, true);
      return;
    }
    const generation = chain.generations[chain.generationIndex];
    const raw = generation.gain * this.chainMultiplier(chain);
    const contribution = Number.isFinite(raw) ? Math.max(0, raw) : 0;
    let amount = contribution;

    if (chain.softCapped && contribution > 0) {
      chain.rawEarned = Math.min(Number.MAX_VALUE, chain.rawEarned + contribution);
      const total = getSoftCappedEcho(chain.rawEarned, chain.capBase);
      amount = Math.max(0, total - chain.softenedEarned);
      chain.softenedEarned = total;
    }

    if (amount > 0) {
      this.state.echo += amount;
      this.state.lifetimeEcho += amount;
    }
    if (this.state.lifetimeEcho >= 1e6) this.checkAchievement('echo_1m');
    if (this.state.lifetimeEcho >= 1000) this.recordStoryBeat('first_echoes');
    chain.earned += amount;
    chain.generationIndex++;

    if (chain.softCapped && chain.rawEarned >= chain.capBase * SOFT_CAP_RAW_LIMIT) {
      this.endChain(chain, true);
    } else if (chain.generationIndex >= chain.generations.length) {
      this.endChain(chain, true);
    }
  }

  endChain(chain, natural) {
    if (!chain.alive) return;
    chain.alive = false;
    const s = this.state;
    s.stats.maxChainGenerations = Math.max(s.stats.maxChainGenerations, chain.generations.length);
    if (chain.generations.length >= 50) this.checkAchievement('chain_50');
    if (natural && !chain.chorus) {
      const reward = this.silenceReward(chain.generations.length);
      if (reward > 0) {
        s.silence += reward;
        s.lifetimeSilence += reward;
        s.silenceThisCycle += reward;
        this.checkAchievement('first_silence');
        this.emitEvent('silence', { amount: reward });
      }
      s.lastChain = { start: chain.start, frequency: chain.frequency };
    }
    this.checkDiscoveries();
    this.checkStoryMilestones();
  }

  emit(frequency = this.state.frequency) {
    const s = this.state;
    if (s.breath < 1) {
      this.emitEvent('notice', { key: '发声需要至少 1 点余息。' });
      return false;
    }
    s.stats.emitted++;
    if (s.stats.emitted === 1) this.checkAchievement('first_emit');
    if (Math.abs(frequency - s.previousFrequency) < 1) s.combo = Math.min(10, s.combo + 1);
    else {
      s.combo = 0;
      s.previousFrequency = frequency;
    }

    s.breath--;
    const active = this.activeChains(true);
    if (active.length >= s.polyphony) this.endChain(active[0], false);
    const ignoresDecay = s.freeDecayChains > 0;
    if (ignoresDecay) s.freeDecayChains--;
    const chain = this.createChain(s.v0 * this.comboMultiplier(), frequency, ignoresDecay);
    s.chains.push(chain);
    this.settle(chain);

    for (const other of this.activeChains(true)) {
      if (other === chain) continue;
      const relation = getFrequencyRelation(chain.frequency, other.frequency, s.interferenceBoost);
      if (relation.type === 'interference') {
        s.stats.interfered++;
        this.checkAchievement('first_interfere');
      } else if (relation.multiplier > 1) {
        s.stats.resonated++;
        s.resonance++;
        this.checkAchievement('first_resonate');
      }
    }
    this.checkDiscoveries();
    this.checkStoryMilestones();
    this.emitEvent('emit', { frequency });
    return true;
  }

  activateAbility(id) {
    const s = this.state;
    if (id === 'listen' && s.silence >= 5) {
      s.silence -= 5;
      s.totalSilenceSpent += 5;
      s.breath = Math.min(s.maxBreath, s.breath + 50);
      return true;
    }
    if (id === 'stillness' && s.silence >= 10) {
      s.silence -= 10;
      s.totalSilenceSpent += 10;
      s.freeDecayChains++;
      return true;
    }
    if (id === 'replay' && s.silence >= 30 && s.lastChain) {
      s.silence -= 30;
      s.totalSilenceSpent += 30;
      const chain = this.createChain(s.lastChain.start * 0.5, s.lastChain.frequency);
      s.chains.push(chain);
      this.settle(chain);
      return true;
    }
    if (id === 'chorus' && s.breath >= 10 && s.silence >= 20) {
      const spent = Math.floor(s.silence / 2);
      s.breath = 0;
      s.silence -= spent;
      s.totalSilenceSpent += spent;
      const start = (s.v0 + s.polyphony * 50) * (1 + spent / 50);
      const chain = this.createChain(start, 50, true, true);
      s.chains.push(chain);
      this.settle(chain);
      return true;
    }
    this.emitEvent('notice', { key: '资源不足。' });
    return false;
  }

  buyUpgrade(id) {
    const upgrade = UPGRADE_DATA.find(item => item.id === id);
    if (!upgrade) return false;
    const level = this.state.levels[id];
    const cost = this.getUpgradeCost(upgrade);
    if (level >= upgrade.max || this.state.echo < cost) return false;
    this.state.echo -= cost;
    this.state.levels[id]++;
    this.recompute();
    this.recordStoryBeat('first_upgrade');
    return true;
  }

  buySoundscape(index) {
    const soundscape = SOUNDSCAPES[index];
    if (!soundscape || this.state.soundscapes[index] || this.state.silence < soundscape.cost) return false;
    this.state.silence -= soundscape.cost;
    this.state.totalSilenceSpent += soundscape.cost;
    this.state.soundscapes[index] = true;
    this.recompute();
    this.recordStoryBeat('first_soundscape');
    return true;
  }

  unlockSource(index) {
    const source = this.state.sources[index];
    const config = SOURCE_DATA[index];
    if (!source || !config || source.unlocked || this.state.echo < config.cost) return false;
    this.state.echo -= config.cost;
    source.unlocked = true;
    if (this.state.sources.every(item => item.unlocked)) this.checkAchievement('all_sources');
    this.checkStoryMilestones();
    return true;
  }

  buyPermanentUpgrade(id) {
    const upgrade = PRESTIGE_DATA.find(item => item.id === id);
    if (!upgrade) return false;
    const cost = this.getPrestigeCost(upgrade);
    if (this.state.echoPoints < cost) return false;
    this.state.echoPoints -= cost;
    this.state.permanent[id]++;
    this.recompute();
    return true;
  }

  buyRelic(id) {
    const relic = ENDGAME_RELICS.find(item => item.id === id);
    if (!relic) return false;
    const level = this.state.relics[id];
    const cost = (level + 1) * 3;
    if (this.state.eternalLevel < 1 || level >= relic.max || this.state.stardust < cost) return false;
    this.state.stardust -= cost;
    this.state.relics[id]++;
    this.recordStoryBeat('relic_first');
    return true;
  }

  nextAscensionTier() {
    return ASCENSION_TIERS[this.state.cosmicTier] || null;
  }

  storyChapterUnlocked(id) {
    const s = this.state;
    const chapter = STORY_CHAPTERS.find(item => item.id === id);
    if (!chapter) return false;
    const milestones = {
      firstEmit: s.stats.emitted > 0,
      echo1000: s.lifetimeEcho >= 1000,
      firstSilence: s.lifetimeSilence > 0,
      eternal: s.eternalLevel >= 1,
      voyageReady: s.eternalLevel >= 2,
      voyage: s.cosmicTier >= 1,
      nebula: s.cosmicTier >= 2,
      finale: s.cosmicTier >= 3,
      starGate: s.cosmicTier >= 4,
      timefold: s.cosmicTier >= 5,
      worldheart: s.cosmicTier >= 6
    };
    return Boolean(milestones[chapter.unlock]);
  }

  advanceTier() {
    const tier = this.nextAscensionTier();
    const s = this.state;
    if (!tier || s.eternalLevel < tier.eternalLevel || s.stardust < tier.stardustCost) {
      this.emitEvent('notice', { key: '层级推进条件尚未满足。' });
      return false;
    }

    const meta = {
      echoPoints: s.echoPoints,
      eternalLevel: s.eternalLevel,
      cosmicTier: s.cosmicTier + 1,
      silenceThisCycle: s.silenceThisCycle,
      lifetimeEcho: s.lifetimeEcho,
      lifetimeSilence: s.lifetimeSilence,
      totalSilenceSpent: s.totalSilenceSpent,
      permanent: { ...s.permanent },
      achievements: { ...s.achievements },
      stats: { ...s.stats },
      soundEnabled: s.soundEnabled,
      language: s.language,
      theme: s.theme,
      stardust: s.stardust - tier.stardustCost,
      relics: { ...s.relics },
      discoveries: { ...s.discoveries },
      storyBeats: { ...s.storyBeats },
      globalBonus: s.globalBonus,
      interferenceBoost: s.interferenceBoost,
      silenceBoost: s.silenceBoost
    };
    this.resetRun(meta);
    this.recordStoryBeat(`tier_${tier.id}`);
    this.emitEvent('tier', { id: tier.id, name: tier.name });
    return true;
  }

  resetRun(meta) {
    this.state = { ...createInitialState(), ...meta };
    this.state.sources = createSources(SOURCE_DATA);
    this.state.breath = 20 + this.state.permanent.initBreath * 10;
    this.state.echo = this.state.permanent.startEcho * 100;
    this.recompute();
    this.checkDiscoveries();
  }

  prestige() {
    const cost = this.getFinalCost();
    if (this.state.silence < cost) {
      this.emitEvent('notice', { key: '需要更多暗寂才能长明。' });
      return false;
    }
    const starDustGain = Math.max(1, Math.floor(this.getPrestigeGain() / 5));
    const meta = {
      echoPoints: this.state.echoPoints + this.getPrestigeGain(),
      eternalLevel: this.state.eternalLevel + 1,
      cosmicTier: this.state.cosmicTier,
      silenceThisCycle: 0,
      lifetimeSilence: this.state.lifetimeSilence,
      totalSilenceSpent: this.state.totalSilenceSpent,
      permanent: { ...this.state.permanent },
      achievements: { ...this.state.achievements },
      stats: { ...this.state.stats, resets: this.state.stats.resets + 1 },
      soundEnabled: this.state.soundEnabled,
      language: this.state.language,
      theme: this.state.theme,
      stardust: this.state.stardust + starDustGain,
      relics: { ...this.state.relics },
      discoveries: { ...this.state.discoveries },
      storyBeats: { ...this.state.storyBeats },
      globalBonus: this.state.globalBonus,
      interferenceBoost: this.state.interferenceBoost,
      silenceBoost: this.state.silenceBoost
    };
    this.resetRun(meta);
    this.checkAchievement('first_reset');
    this.checkStoryMilestones();
    this.recompute();
    this.emitEvent('prestige', { level: this.state.eternalLevel, stardust: starDustGain });
    return true;
  }

  hardReset() {
    const fresh = createInitialState();
    fresh.sources = createSources(SOURCE_DATA);
    this.state = fresh;
    this.recompute();
  }

  update(deltaSeconds) {
    const s = this.state;
    const delta = Math.min(Math.max(0, deltaSeconds), MAX_DELTA);
    s.time += delta;
    s.breath = Math.min(s.maxBreath, s.breath + s.breathRate * delta);
    this.tickSources(delta);

    for (const chain of s.chains) {
      if (!chain.alive) continue;
      chain.elapsed += delta;
      let safety = 0;
      while (chain.alive && chain.elapsed >= chain.nextAt && safety++ < 250) {
        this.settle(chain);
        if (chain.alive) chain.nextAt += chain.interval;
      }
    }
    s.chains = s.chains.filter(chain => chain.alive);
  }

  tickSources(delta) {
    for (const source of this.state.sources) {
      if (!source.unlocked) continue;
      source.timer += delta;
      if (source.timer < source.interval) continue;
      source.timer %= source.interval;
      if (this.activeChains(true).length >= this.state.polyphony) continue;
      const chain = this.createChain(this.state.v0 * 0.5, source.frequency);
      this.state.chains.push(chain);
      this.settle(chain);
    }
  }

  projectedWave() {
    const plan = this.planChain(this.state.v0 * this.comboMultiplier(), false, false);
    return {
      generations: plan.count,
      totalEcho: plan.total * this.globalMultiplier(),
      silence: this.silenceReward(plan.count)
    };
  }

  toJSON() {
    const s = this.state;
    return {
      version: 2,
      breath: s.breath,
      echo: s.echo,
      silence: s.silence,
      lifetimeEcho: s.lifetimeEcho,
      lifetimeSilence: s.lifetimeSilence,
      totalSilenceSpent: s.totalSilenceSpent,
      freq: s.frequency,
      lv: s.levels,
      echoPoints: s.echoPoints,
      permLevel: s.eternalLevel,
      prestigeLv: s.permanent,
      resonance: s.resonance,
      ambience: s.soundscapes,
      sources: s.sources.map(source => ({
        unlocked: source.unlocked,
        freq: source.frequency,
        interval: source.interval,
        timer: source.timer
      })),
      achievements: s.achievements,
      interfereBuff: s.interferenceBoost,
      silenceBoost: s.silenceBoost,
      pendingSilenceCount: s.freeDecayChains,
      lastChainInfo: s.lastChain && { V0: s.lastChain.start, freq: s.lastChain.frequency },
      soundOn: s.soundEnabled,
      language: s.language,
      theme: s.theme,
      stats: s.stats,
      endgame: {
        stardust: s.stardust,
        relics: s.relics,
        cosmicTier: s.cosmicTier,
        discoveries: s.discoveries,
        storyBeats: s.storyBeats
      },
      silenceThisCycle: s.silenceThisCycle,
      globalMult: s.globalBonus || 1
    };
  }
}
