import { GameEngine, loadLegacyState } from './engine.js';
import { translate } from './i18n.js';
import { WaveformRenderer } from './waveform.js';
import { createSaveFile, loadSave, parseSaveFile, SAVE_KEY, LEGACY_SAVE_KEY, writeSave } from './storage.js';
import { SoundEffects } from './audio.js';
import { renderNavigation, renderPanel, updateCore, updateResources } from './ui.js';

const $ = selector => document.querySelector(selector);
const sound = new SoundEffects();
let activeView = 'upgrades';
let toastTimeout;
let engine;
let waveform;

try {
  const { state, migrated } = loadSave();
  engine = new GameEngine(state);
  if (migrated) writeSave(engine);
} catch (error) {
  console.error('Unable to load the Cry & Bright save.', error);
  engine = new GameEngine(loadLegacyState(null));
  showToast('存档读取失败，已启动新进度。');
}

document.body.dataset.theme = engine.state.theme;
document.documentElement.lang = engine.state.language;
waveform = new WaveformRenderer($('#wave-viewport'), $('#wave-canvas'));
renderStaticLocale();
renderNavigation(activeView, engine.state.language, engine.state.eternalLevel);
renderPanel(engine, activeView);
renderEverything();

if (engine.state.language !== 'en-US' && engine.state.stats.emitted === 0) {
  showToast('欢迎来到鸣与明。');
}

function renderStaticLocale() {
  const language = engine.state.language;
  document.documentElement.lang = language;
  document.querySelectorAll('[data-i18n]').forEach(element => {
    element.textContent = translate(element.dataset.i18n, language);
  });
  document.title = language === 'en-US' ? 'Cry & Bright — Listen to the shape of the universe' : 'Cry & Bright — 鸣与明';
  $('#frequency-slider').setAttribute('aria-label', translate('频率', language));
}

function renderEverything() {
  updateResources(engine);
  updateCore(engine, waveform);
  const relation = engine.activeChains(true).reduce((best, chain) => {
    const result = frequencyRelation(engine.state.frequency, chain.frequency);
    if (result.type === 'interference') return result;
    return result.multiplier > (best?.multiplier || 1) ? result : best;
  }, null);
  const relationLabels = {
    interference: '干涉',
    octave: '八度',
    fifth: '五度',
    third: '三度',
    neutral: '等待信号'
  };
  $('#signal-frequency').textContent = engine.state.frequency;
  $('#footer-frequency').textContent = engine.state.frequency;
  $('#signal-global').textContent = `×${engine.globalMultiplier().toFixed(2)}`;
  $('#signal-relation').textContent = translate(relationLabels[relation?.type || 'neutral'], engine.state.language);
  $('#signal-relation').dataset.relation = relation?.type || 'neutral';
  $('#signal-meter span').style.width = `${engine.state.frequency}%`;
}

function playSound(frequency, duration = 0.16, volume = 0.035) {
  if (engine.state.soundEnabled) sound.play(frequency, duration, volume);
}

function frequencyRelation(first, second) {
  const distance = Math.abs(first - second);
  if (distance < 5) return { type: 'interference', multiplier: 0.5 };
  if (distance >= 47 && distance <= 53) return { type: 'octave', multiplier: 2 };
  if (distance >= 32 && distance <= 42) return { type: 'fifth', multiplier: 1.5 };
  if (distance >= 15 && distance <= 25) return { type: 'third', multiplier: 1.25 };
  return { type: 'neutral', multiplier: 1 };
}

function refreshPanel() {
  renderNavigation(activeView, engine.state.language, engine.state.eternalLevel);
  renderPanel(engine, activeView);
}

function showToast(message) {
  const toast = $('#toast');
  toast.textContent = translate(message, engine?.state.language || 'zh-CN');
  toast.classList.add('visible');
  clearTimeout(toastTimeout);
  toastTimeout = setTimeout(() => toast.classList.remove('visible'), 2600);
}

function persist() {
  try {
    writeSave(engine);
  } catch (error) {
    console.error('Unable to save Cry & Bright progress.', error);
    showToast('存档失败，请检查浏览器本地存储设置。');
  }
}

function actionButton(action, element) {
  switch (action) {
    case 'emit':
      if (engine.emit(engine.state.frequency)) playSound(180 + engine.state.frequency * 5, 0.18);
      break;
    case 'ability':
      if (engine.activateAbility(element.dataset.id)) playSound(220, 0.28);
      break;
    case 'buy-upgrade':
      if (engine.buyUpgrade(element.dataset.id)) playSound(380, 0.12);
      else showToast('资源不足。');
      break;
    case 'buy-soundscape':
      if (engine.buySoundscape(Number(element.dataset.index))) playSound(260, 0.28);
      else showToast('资源不足。');
      break;
    case 'unlock-source':
      if (engine.unlockSource(Number(element.dataset.index))) playSound(480, 0.18);
      else showToast('资源不足。');
      break;
    case 'buy-prestige':
      if (engine.buyPermanentUpgrade(element.dataset.id)) playSound(520, 0.16);
      else showToast('资源不足。');
      break;
    case 'buy-relic':
      if (engine.buyRelic(element.dataset.id)) playSound(700, 0.2);
      else showToast('资源不足。');
      break;
    case 'advance-tier':
      if (!window.confirm(translate('确认推进层级？这将清空当轮资源、声源、声场与普通升级。', engine.state.language))) return;
      if (!engine.advanceTier()) {
        break;
      }
      activeView = 'expedition';
      playSound(760, 0.6, 0.05);
      break;
    case 'prestige':
      if (engine.state.silence < engine.getFinalCost()) {
        engine.prestige();
        break;
      }
      if (window.confirm(translate('确认长明？这将重置当前轮回进度。', engine.state.language))) {
        const level = engine.state.eternalLevel + 1;
        if (engine.prestige()) {
          activeView = 'prestige';
          showToast(`${translate('长明完成', engine.state.language)} · Lv.${level}`);
          playSound(620, 0.8, 0.06);
        }
      }
      break;
    case 'toggle-sound':
      engine.state.soundEnabled = !engine.state.soundEnabled;
      break;
    case 'export-save':
      exportSave();
      return;
    case 'import-save':
      $('#import-file').click();
      return;
    case 'hard-reset':
      if (!window.confirm(translate('确定清空所有存档与成就？', engine.state.language))) return;
      engine.hardReset();
      activeView = 'upgrades';
      try {
        localStorage.removeItem(SAVE_KEY);
        localStorage.removeItem(LEGACY_SAVE_KEY);
      } catch (error) {
        console.error('Unable to clear Cry & Bright save.', error);
      }
      break;
    default:
      return;
  }
  refreshPanel();
  renderEverything();
  persist();
}

function exportSave() {
  const url = URL.createObjectURL(createSaveFile(engine));
  const link = document.createElement('a');
  link.href = url;
  link.download = `cry-bright-save-${new Date().toISOString().slice(0, 10)}.json`;
  link.click();
  URL.revokeObjectURL(url);
  showToast('存档已导出。');
}

async function importSave(file) {
  if (!file) return;
  try {
    const imported = parseSaveFile(await file.text());
    engine = new GameEngine(imported);
    document.body.dataset.theme = engine.state.theme;
    activeView = 'upgrades';
    renderStaticLocale();
    refreshPanel();
    renderEverything();
    persist();
    showToast('存档导入成功。');
  } catch (error) {
    console.error('Unable to import Cry & Bright save.', error);
    showToast('存档文件无效。');
  }
  $('#import-file').value = '';
}

document.addEventListener('click', event => {
  const viewButton = event.target.closest('[data-view]');
  if (viewButton) {
    activeView = viewButton.dataset.view;
    refreshPanel();
    return;
  }
  const action = event.target.closest('[data-action]');
  if (action) actionButton(action.dataset.action, action);
});

$('#frequency-slider').addEventListener('input', event => {
  engine.state.frequency = Number(event.target.value);
  renderEverything();
});

document.addEventListener('input', event => {
  const input = event.target.closest('[data-source-frequency]');
  if (!input) return;
  const source = engine.state.sources[Number(input.dataset.sourceFrequency)];
  if (!source?.unlocked) return;
  source.frequency = Number(input.value);
  input.previousElementSibling.querySelector('output').value = String(source.frequency);
  persist();
});

document.addEventListener('change', event => {
  if (event.target.id === 'theme-select') {
    engine.state.theme = event.target.value;
    document.body.dataset.theme = event.target.value;
    waveform.resize();
    renderEverything();
    persist();
  } else if (event.target.id === 'language-select') {
    engine.state.language = event.target.value;
    renderStaticLocale();
    refreshPanel();
    renderEverything();
    persist();
  } else if (event.target.id === 'import-file') {
    importSave(event.target.files?.[0]);
  }
});

document.addEventListener('keydown', event => {
  if (event.code !== 'Space' || event.repeat || event.target.closest('button, input, select, textarea, [contenteditable="true"]')) return;
  event.preventDefault();
  actionButton('emit', $('#emit-button'));
});

window.addEventListener('beforeunload', persist);

let last = performance.now();
let uiElapsed = 0;
let saveElapsed = 0;
function frame(now) {
  const delta = Math.min((now - last) / 1000, 0.1);
  last = now;
  engine.update(delta);
  for (const event of engine.drainEvents()) {
    if (event.type === 'achievement') showToast(`✦ ${translate(event.name, engine.state.language)}`);
    else if (event.type === 'silence') showToast(`◍ +${event.amount.toFixed(1)} ${translate('暗寂', engine.state.language)}`);
    else if (event.type === 'tier') showToast(`${translate(event.name, engine.state.language)} · ${translate('信标已点亮', engine.state.language)}`);
    else if (event.type === 'discovery') showToast(`✦ ${translate('深空发现', engine.state.language)}：${translate(event.name, engine.state.language)}`);
    else if (event.type === 'story') {
      showToast(`▤ ${translate(event.title, engine.state.language)}`);
      if (activeView === 'story') renderPanel(engine, activeView);
      persist();
    }
    else if (event.type === 'notice') showToast(event.key);
  }
  waveform.render(engine);
  uiElapsed += delta;
  if (uiElapsed >= 0.12) {
    uiElapsed = 0;
    updateResources(engine);
    updateCore(engine, waveform);
    const current = $('#signal-frequency');
    if (current) current.textContent = engine.state.frequency;
    const footer = $('#footer-frequency');
    if (footer) footer.textContent = engine.state.frequency;
  }
  saveElapsed += delta;
  if (saveElapsed >= 5) {
    saveElapsed = 0;
    persist();
  }
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
