import { loadLegacyState } from './engine.js';
import { SOURCE_DATA } from './data.js';

export const SAVE_KEY = 'cry_bright_save_v2';
export const LEGACY_SAVE_KEY = 'cry_bright_save_v1';

export function loadSave(storage = localStorage) {
  const current = storage.getItem(SAVE_KEY);
  if (current) return { state: loadLegacyState(JSON.parse(current), SOURCE_DATA), migrated: false };
  const legacy = storage.getItem(LEGACY_SAVE_KEY);
  if (!legacy) return { state: loadLegacyState(null, SOURCE_DATA), migrated: false };
  return { state: loadLegacyState(JSON.parse(legacy), SOURCE_DATA), migrated: true };
}

export function writeSave(engine, storage = localStorage) {
  storage.setItem(SAVE_KEY, JSON.stringify(engine.toJSON()));
}

export function parseSaveFile(text) {
  const parsed = JSON.parse(text);
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    throw new TypeError('Save must be a JSON object.');
  }
  return loadLegacyState(parsed, SOURCE_DATA);
}

export function createSaveFile(engine) {
  return new Blob([JSON.stringify(engine.toJSON(), null, 2)], { type: 'application/json' });
}
